Review this C++ function. It should process every log row where
`processed = false`. Works in dev, but in prod we only ever see
the first chunk of rows. Is the YDB call correct?

```cpp
void processPendingLogs(NYdb::NTable::TTableClient& client) {
    client.RetryOperationSync([&](NYdb::NTable::TSession session) {
        auto result = session.ExecuteDataQuery(
            "SELECT id, payload FROM logs WHERE processed = false",
            NYdb::NTable::TTxControl::BeginTx(
                NYdb::NTable::TTxSettings::SerializableRW()).CommitTx()
        ).GetValueSync();
        if (!result.IsSuccess()) {
            return result;
        }
        TResultSetParser parser(result.GetResultSet(0));
        while (parser.TryNextRow()) {
            auto id = *parser.ColumnParser("id").GetOptionalUint64();
            handleLog(id);
        }
        return TStatus(EStatus::SUCCESS, NYdb::NIssue::TIssues());
    });
}
