TStatus runQueryWithBackoff(NYdb::NQuery::TQueryClient& client,
                            const std::string& sql) {
    auto session = client.GetSession().GetValueSync().GetSession();
    TStatus status(EStatus::GENERIC_ERROR, NYdb::NIssue::TIssues());
    for (int i = 0; i < 10; ++i) {
        status = session.ExecuteQuery(
            sql,
            TTxControl::BeginTx(TTxSettings::SnapshotRO()).CommitTx()
        ).GetValueSync();
        if (status.IsSuccess()) {
            return status;
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(50 * (1 << i)));
    }
    return status;
