Review this C++ export job. It streams seasons for billing. We
occasionally double-charge after network blips. Is the stream
handling correct?

```cpp
void billSeasons(NYdb::NQuery::TQueryClient& client) {
    ThrowOnError(client.RetryQuerySync([&](NYdb::NQuery::TSession session) -> TStatus {
        auto stream = session.StreamExecuteQuery(
            "SELECT series_id, season_id FROM seasons",
            TTxControl::NoTx()
        ).GetValueSync();
        if (!stream.IsSuccess()) {
            return stream;
        }
        bool eos = false;
        while (!eos) {
            auto part = stream.ReadNext().ExtractValueSync();
            if (!part.IsSuccess()) {
                eos = true;
                if (!part.EOS()) {
                    return part;
                }
                continue;
            }
            if (part.HasResultSet()) {
                TResultSetParser parser(part.ExtractResultSet());
                while (parser.TryNextRow()) {
                    auto seriesId = *parser.ColumnParser("series_id")
                        .GetOptionalUint64();
                    auto seasonId = *parser.ColumnParser("season_id")
                        .GetOptionalUint64();
                    chargeCustomer(seriesId, seasonId);
                }
            }
        }
        return TStatus(EStatus::SUCCESS, NYdb::NIssue::TIssues());
    }));
}
