TStatus ensureTenantTableAndInsert(NYdb::NTable::TTableClient& client,
                                   const std::string& tablePath,
                                   uint64_t eventId,
                                   const std::string& payload) {
    return client.RetryOperationSync(
        [&](NYdb::NTable::TSession session) -> NYdb::TStatus {
            auto createStatus = session.ExecuteSchemeQuery(
                "CREATE TABLE IF NOT EXISTS `" + tablePath + "` ("
                "  id Uint64,"
                "  payload Utf8,"
                "  PRIMARY KEY (id))"
            ).GetValueSync();
            if (!createStatus.IsSuccess()) {
