                .AddParam("$id").Uint64(eventId).Build()
                .AddParam("$payload").Utf8(payload).Build()
                .Build();
            return session.ExecuteDataQuery(
                "UPSERT INTO `" + tablePath + "` (id, payload) "
                "VALUES ($id, $payload)",
                NYdb::NTable::TTxControl::BeginTx(
                    NYdb::NTable::TTxSettings::SerializableRW()).CommitTx(),
                params
            ).GetValueSync();
        },
        NYdb::NTable::TRetryOperationSettings().Idempotent(true));
}
